"use client";
/* Nomad, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Nomad(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("nomad"); }, []);
  return React.createElement("piix-pal", { "pal": "nomad", ...piixAttrs(props) });
}

export default Nomad;
